create extension if not exists pgcrypto;
create table if not exists public.employees (id uuid primary key default gen_random_uuid(), document text not null unique, full_name text not null, role text not null default '', daily_rate numeric(14,2) not null default 0 check(daily_rate>=0), active boolean not null default true, hire_date date, notes text, created_at timestamptz not null default now());
create table if not exists public.attendance (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id), work_date date not null, created_at timestamptz not null default now(), unique(employee_id,work_date));
create table if not exists public.advances (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id), advance_date date not null, amount numeric(14,2) not null check(amount>0), description text default '', applied_amount numeric(14,2) not null default 0 check(applied_amount>=0 and applied_amount<=amount), created_at timestamptz not null default now());
create table if not exists public.credits (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id), credit_date date not null, amount numeric(14,2) not null check(amount>0), description text default '', balance numeric(14,2) not null check(balance>=0), created_at timestamptz not null default now());
create table if not exists public.credit_payments (id uuid primary key default gen_random_uuid(), credit_id uuid not null references public.credits(id), payroll_period date not null, amount numeric(14,2) not null check(amount>0), created_at timestamptz not null default now());
create table if not exists public.payroll_adjustments (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id), period date not null, overtime numeric(14,2) not null default 0, tips numeric(14,2) not null default 0, created_at timestamptz not null default now(), unique(employee_id,period));
create table if not exists public.payrolls (id uuid primary key default gen_random_uuid(), period date not null unique, status text not null default 'open' check(status in ('open','closed')), snapshot jsonb, closed_at timestamptz, created_at timestamptz not null default now());
-- Antes de cargar información personal, configura Auth y políticas RLS restrictivas. No habilites acceso anónimo a estas tablas.
